import { z } from 'zod';

const SHOP_LOCATION_CACHE_KEY = 'shop:last-known-location:v1';

const lastKnownPositionSchema = z.object({
  version: z.literal(1),
  latitude: z.number().finite().min(-90).max(90),
  longitude: z.number().finite().min(-180).max(180),
  capturedAt: z.number().int().nonnegative(),
});

export type LastKnownPosition = Omit<z.infer<typeof lastKnownPositionSchema>, 'version'>;

export type LocationStorage = Pick<Storage, 'getItem' | 'setItem' | 'removeItem'>;

export const getShopLocationSessionStorage = (): LocationStorage | undefined => {
  try {
    return window.sessionStorage;
  } catch {
    return undefined;
  }
};

export const readLastKnownPosition = (
  storage: LocationStorage | undefined = getShopLocationSessionStorage(),
): LastKnownPosition | null => {
  if (!storage) return null;

  try {
    const serializedPosition = storage.getItem(SHOP_LOCATION_CACHE_KEY);
    if (!serializedPosition) return null;

    const parsedPosition = lastKnownPositionSchema.safeParse(JSON.parse(serializedPosition));
    if (!parsedPosition.success) {
      storage.removeItem(SHOP_LOCATION_CACHE_KEY);
      return null;
    }

    const { latitude, longitude, capturedAt } = parsedPosition.data;
    return { latitude, longitude, capturedAt };
  } catch {
    return null;
  }
};

export const writeLastKnownPosition = (
  position: LastKnownPosition,
  storage: LocationStorage | undefined = getShopLocationSessionStorage(),
) => {
  if (!storage) return;

  try {
    storage.setItem(
      SHOP_LOCATION_CACHE_KEY,
      JSON.stringify({
        version: 1,
        ...position,
      }),
    );
  } catch {
    // A location result should still be usable when session storage is unavailable.
  }
};

export const clearLastKnownPosition = (storage: LocationStorage | undefined = getShopLocationSessionStorage()) => {
  if (!storage) return;

  try {
    storage.removeItem(SHOP_LOCATION_CACHE_KEY);
  } catch {
    // Clearing an unavailable storage implementation is already effectively complete.
  }
};
